function mudarTab(tabName, btnElement) {
    document.querySelectorAll('.tab-content').forEach(d => d.classList.remove('active'));
    document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
    
    document.getElementById('tab-'+tabName).classList.add('active');
    if(btnElement) btnElement.classList.add('active');
    
    if(tabName === 'historico') renderizarHistorico();
    if(tabName === 'estatisticas') { renderizarEstatisticas(); renderizarTabelaPAC(); }
    if(tabName === 'alunos') atualizarListasDeAlunosUI();
}

const canvasEl = document.getElementById('canvas');
const ctx = canvasEl ? canvasEl.getContext('2d', { willReadFrequently: true }) : null; 

if(document.getElementById('uploadInput')) {
    document.getElementById('uploadInput').addEventListener('change', e => {
        const f = e.target.files[0]; if(!f) return;
        const r = new FileReader();
        r.onload = ev => { imgAtual.src = ev.target.result; imgAtual.onload = () => resetZoom(); }
        r.readAsDataURL(f);
    });
}

function redesenhar() {
    if(!imgAtual.src || !canvasEl) return;
    canvasEl.width = imgAtual.width; canvasEl.height = imgAtual.height;
    canvasEl.style.width = (imgAtual.width * zoomLevel) + "px";
    canvasEl.style.height = (imgAtual.height * zoomLevel) + "px";
    ctx.drawImage(imgAtual, 0, 0);
}

function ajustarZoom(d) { if(!imgAtual.src)return; zoomLevel+=d; if(zoomLevel<0.1)zoomLevel=0.1; redesenhar(); }
function resetZoom() { if(!imgAtual.src)return; zoomLevel = (document.querySelector('.canvas-area').clientWidth-60)/imgAtual.width; if(zoomLevel>1)zoomLevel=1; redesenhar(); }

// ==========================================
// MOTOR DE CORREÇÃO
// ==========================================
function executarCorrecao() {
    if(!imgAtual.src) return alert("Carregue a imagem da prova primeiro!");
    if(configAtual.mapa.length === 0) return alert("Esta turma ainda não foi mapeada! Por favor, cole as coordenadas no código.");

    const nomeAluno = document.getElementById('nomeAluno').value || "Aluno Não Identificado";
    const notaRedacao = parseFloat(document.getElementById('notaRedacao').value) || 0;

    if(!document.getElementById('nomeAluno').value) {
        if(!confirm("Você não selecionou um aluno na lista. Deseja corrigir mesmo assim como 'Aluno Não Identificado'?")) return;
    }

    let gabaritoUnificado = {};
    const txtFull = Object.values(gabaritoMestreDB).join(" ");
    const regex = /(\d+)[\s-.]*([A-ENX])/gi;
    let match;
    while ((match = regex.exec(txtFull)) !== null) gabaritoUnificado[parseInt(match[1])] = match[2].toUpperCase();

    if(Object.keys(gabaritoUnificado).length === 0) return alert("O gabarito desta turma está vazio na nuvem.");

    ctx.drawImage(imgAtual, 0, 0);
    let respAluno = {};
    
    configAtual.mapa.forEach(z => {
        const data = ctx.getImageData(z.x-(z.w/2), z.y-(z.h/2), z.w, z.h).data;
        let escuro = 0;
        for(let i=0; i<data.length; i+=16) if(((data[i]+data[i+1]+data[i+2])/3) < 140) escuro++;
        if((escuro/(data.length/16)) > 0.35) if(!respAluno[z.questao]) respAluno[z.questao] = z.alt;
    });

    let totalPontos = 0; 
    let htmlBlocos = "";
    let htmlPdf = "";
    let totalQuestoesProva = 0;
    
    let errosDoAluno =[];
    let notaBloco1 = 0, notaBloco2 = 0, notaBloco3 = 0, notaBloco4 = 0;
    
    const isEnsinoMedio = configAtual.nome.includes("Médio");
    const isFund9 = configAtual.nome.includes("9º");
    const isFund678 = configAtual.nome.includes("6º") || configAtual.nome.includes("7º") || configAtual.nome.includes("8º");

    configAtual.blocos.forEach((bloco, index) => {
        let pontosB = 0; let totalQ = 0; let linhas = ""; let pdfLinhas = "";
        
        bloco.materias.forEach(nomeMat => {
            const disc = configAtual.materias.find(d => d.nome === nomeMat);
            if(disc) {
                let acertosM = 0;
                for(let q=disc.inicio; q<(disc.inicio+disc.qtd); q++) {
                    const alu = respAluno[q]; 
                    const prof = gabaritoUnificado[q];
                    const isNula = (prof === 'N' || prof === 'X');

                    if (isNula) {
                        acertosM++; 
                        const todasOpcoesQ = configAtual.mapa.filter(m => m.questao == q);
                        todasOpcoesQ.forEach(zOp => { ctx.lineWidth = 3; ctx.strokeStyle = "#007bff"; ctx.strokeRect(zOp.x-(zOp.w/2), zOp.y-(zOp.h/2), zOp.w, zOp.h); });
                        if(alu) { const zAlu = configAtual.mapa.find(m => m.questao==q && m.alt==alu); if(zAlu) { ctx.lineWidth = 6; ctx.strokeStyle = "#007bff"; ctx.strokeRect(zAlu.x-(zAlu.w/2), zAlu.y-(zAlu.h/2), zAlu.w, zAlu.h); } }
                    } else {
                        if(alu) { 
                            const z = configAtual.mapa.find(m => m.questao==q && m.alt==alu); 
                            if(z) { 
                                ctx.lineWidth = 5; 
                                if(prof && alu==prof) { 
                                    ctx.strokeStyle="#0b7a25"; acertosM++; 
                                } else { 
                                    ctx.strokeStyle="#c62828"; 
                                    errosDoAluno.push(q);
                                } 
                                ctx.strokeRect(z.x-(z.w/2), z.y-(z.h/2), z.w, z.h); 
                            } 
                        } else {
                            if(prof) errosDoAluno.push(q);
                        }

                        if(prof && alu!=prof) { const zC = configAtual.mapa.find(m => m.questao==q && m.alt==prof); if(zC) { ctx.lineWidth=4; ctx.strokeStyle="#ffc107"; ctx.strokeRect(zC.x-(zC.w/2), zC.y-(zC.h/2), zC.w, zC.h); } }
                    }
                }
                pontosB += acertosM; totalQ += disc.qtd;
                linhas += `<div class="bloco-row"><span>${nomeMat}</span> <b>${acertosM} / ${disc.qtd}</b></div>`;
                pdfLinhas += `<div class="pdf-row"><span>${nomeMat}</span> <span>${acertosM} / ${disc.qtd}</span></div>`;
            }
        });

        if(bloco.nome.includes("BLOCO 01") || bloco.nome.includes("Linguagens")) {
            pontosB += notaRedacao;
            totalQ += 10; 
            linhas += `<div class="bloco-row" style="background: #fff3cd; padding: 4px; border-radius: 3px; color: #856404;"><span>✍️ Redação</span> <b>${notaRedacao.toFixed(1)} / 10.0</b></div>`;
            pdfLinhas += `<div class="pdf-row" style="background: #eee; font-weight: bold; padding: 4px;"><span>Redação</span> <span>${notaRedacao.toFixed(1)} / 10.0</span></div>`;
        }

        let media = 0;
        if (isEnsinoMedio) {
            if (bloco.nome.includes("BLOCO 01") || bloco.nome.includes("Linguagens")) { media = calcularNotaPorEscala(pontosB, ESCALA_MEDIO_B1); } 
            else if (bloco.nome.includes("BLOCO 02") || bloco.nome.includes("Ciências Humanas")) { media = calcularNotaPorEscala(pontosB, ESCALA_MEDIO_B2); } 
            else if (bloco.nome.includes("BLOCO 03") || bloco.nome.includes("Ciências da Natureza")) { media = calcularNotaPorEscala(pontosB, ESCALA_MEDIO_B3); } 
            else if (bloco.nome.includes("BLOCO 04") || bloco.nome.includes("Matemática")) { media = calcularNotaPorEscala(pontosB, ESCALA_MEDIO_B4); } 
            else { media = totalQ > 0 ? (pontosB/totalQ)*10 : 0; }
        } else if (isFund9) {
            if (bloco.nome.includes("BLOCO 01") || bloco.nome.includes("Linguagens")) { media = calcularNotaPorEscala(pontosB, ESCALA_FUND_B1_B2); } 
            else if (bloco.nome.includes("BLOCO 02") || bloco.nome.includes("Ciências Humanas")) { media = calcularNotaPorEscala(pontosB, ESCALA_FUND_B1_B2); } 
            else if (bloco.nome.includes("BLOCO 03") || bloco.nome.includes("Matemática")) { media = calcularNotaPorEscala(pontosB, ESCALA_FUND_B3); } 
            else if (bloco.nome.includes("BLOCO 04") || bloco.nome.includes("Ciências da Natureza")) { media = calcularNotaPorEscala(pontosB, ESCALA_FUND9_B4); } 
            else { media = totalQ > 0 ? (pontosB/totalQ)*10 : 0; }
        } else if (isFund678) {
            if (bloco.nome.includes("BLOCO 01") || bloco.nome.includes("Linguagens")) { media = calcularNotaPorEscala(pontosB, ESCALA_FUND_B1_B2); } 
            else if (bloco.nome.includes("BLOCO 02") || bloco.nome.includes("Ciências Humanas")) { media = calcularNotaPorEscala(pontosB, ESCALA_FUND_B1_B2); } 
            else if (bloco.nome.includes("BLOCO 03") || bloco.nome.includes("Matemática")) { media = calcularNotaPorEscala(pontosB, ESCALA_FUND_B3); } 
            else if (bloco.nome.includes("BLOCO 04") || bloco.nome.includes("Ciências da Natureza")) { media = calcularNotaPorEscala(pontosB, ESCALA_FUND8_B4); } 
            else { media = totalQ > 0 ? (pontosB/totalQ)*10 : 0; }
        } else {
            media = totalQ > 0 ? (pontosB/totalQ)*10 : 0;
        }

        if(index === 0) notaBloco1 = media;
        if(index === 1) notaBloco2 = media;
        if(index === 2) notaBloco3 = media;
        if(index === 3) notaBloco4 = media;

        htmlBlocos += `<div class="bloco-group"><div class="bloco-header">${bloco.nome}</div>${linhas}<div class="bloco-footer"><span>Total: <b>${pontosB.toFixed(1)}/${totalQ}</b></span> <span>Nota Ponderada: ${media.toFixed(1)}</span></div></div>`;
        htmlPdf += `<div class="pdf-bloco"><h3>${bloco.nome}</h3>${pdfLinhas}<div class="pdf-bloco-footer"><span>PONTOS: ${pontosB.toFixed(1)} / ${totalQ}</span><span>NOTA: ${media.toFixed(1)}</span></div></div>`;
        totalPontos += pontosB; totalQuestoesProva += totalQ;
    });

    let percentualAproveitamento = totalQuestoesProva > 0 ? (totalPontos / totalQuestoesProva) * 100 : 0;
    let classeCor = percentualAproveitamento >= 60 ? 'aprovado' : 'reprovado';

    htmlBlocos += `<div class="resumo-final ${classeCor}">PONTUAÇÃO TOTAL: ${totalPontos.toFixed(1)} / ${totalQuestoesProva}</div>`;
    document.getElementById('resultadoBoletim').innerHTML = htmlBlocos;
    document.getElementById('btnPdf').style.display = 'block';

    document.getElementById('pNome').innerText = nomeAluno;
    document.getElementById('pTurma').innerText = configAtual.nome;
    document.getElementById('pData').innerText = new Date().toLocaleDateString();
    document.getElementById('pdfBlocos').innerHTML = htmlPdf;
    
    const divNotaPdf = document.getElementById('pNotaFinal');
    divNotaPdf.innerText = `PONTUAÇÃO TOTAL DA PROVA: ${totalPontos.toFixed(1)} / ${totalQuestoesProva}`;
    divNotaPdf.className = `pdf-nota-final ${classeCor}`;
    
    document.getElementById('imgPrint').src = canvasEl.toDataURL("image/jpeg", 1.0);

    salvarAlunoNoHistorico({
        id: Date.now(), 
        data: new Date().toLocaleDateString(), 
        nome: nomeAluno, 
        turma: configAtual.nome, 
        redacao: notaRedacao.toFixed(1), 
        total: parseFloat(totalPontos.toFixed(1)), 
        b1: notaBloco1.toFixed(1),
        b2: notaBloco2.toFixed(1),
        b3: notaBloco3.toFixed(1),
        b4: notaBloco4.toFixed(1),
        erros: errosDoAluno
    });
}

// ==========================================
// HISTÓRICO NO FIREBASE
// ==========================================
async function carregarHistoricoDoFirebase() {
    if(!db) return;
    try {
        const snapshot = await db.collection("historico").get();
        historicoAlunos =[];
        snapshot.forEach(doc => { historicoAlunos.push(doc.data()); });
        historicoAlunos.sort((a,b) => a.id - b.id);
        renderizarHistorico();
        renderizarEstatisticas(); 
        renderizarTabelaPAC();
    } catch(e) { console.error(e); historicoAlunos =[]; }
}

// Salva o resultado de uma correção no histórico. Se já existir uma correção
// anterior para o MESMO aluno na MESMA turma, o registro antigo é
// automaticamente substituído pelo novo (evita duplicados no Histórico,
// no Ranking e na Tabela PAC).
async function salvarAlunoNoHistorico(obj) {
    const existente = historicoAlunos.find(a => a.nome === obj.nome && a.turma === obj.turma);

    if(existente) {
        historicoAlunos = historicoAlunos.filter(a => a.id !== existente.id);
        if(db) { try { await db.collection("historico").doc(existente.id.toString()).delete(); } catch(e) {} }
    }

    historicoAlunos.push(obj);
    if(db) { try { await db.collection("historico").doc(obj.id.toString()).set(obj); } catch(e) {} }
    renderizarHistorico();
    renderizarEstatisticas();
    renderizarTabelaPAC();
}

async function limparHistoricoBD() { 
    if(confirm(`Apagar TODOS os alunos da turma ${configAtual.nome}?`)) { 
        const filtrados = historicoAlunos.filter(a => a.turma === configAtual.nome);
        historicoAlunos = historicoAlunos.filter(a => a.turma !== configAtual.nome);
        if(db) {
            try {
                const batch = db.batch();
                filtrados.forEach(a => { const ref = db.collection("historico").doc(a.id.toString()); batch.delete(ref); });
                await batch.commit();
            } catch(e){}
        }
        renderizarHistorico(); 
        renderizarEstatisticas();
        renderizarTabelaPAC();
    } 
}

async function apagarItemHistorico(id) {
    if(confirm("Deseja excluir a nota deste aluno?")) {
        historicoAlunos = historicoAlunos.filter(a => a.id !== id);
        if(db) { try { await db.collection("historico").doc(id.toString()).delete(); } catch(e){} }
        renderizarHistorico();
        renderizarEstatisticas();
        renderizarTabelaPAC();
    }
}

function renderizarHistorico() {
    const d = document.getElementById('tabelaHistorico');
    if(!d) return;
    const filtrados = historicoAlunos.filter(a => a.turma === configAtual.nome);
    if(filtrados.length===0) { d.innerHTML=`<p style='text-align:center;color:#999; padding: 20px;'>Nenhum aluno avaliado.</p>`; return; }
    let h = `<table class="historico-table"><thead><tr><th>Data</th><th>Nome do Aluno</th><th>Pontos</th><th style="text-align:center;">Ação</th></tr></thead><tbody>`;
    [...filtrados].reverse().forEach(a => h+=`<tr><td>${a.data}</td><td><strong>${a.nome}</strong></td><td><b>${a.total}</b></td><td style="text-align:center;"><button class="btn-apagar" onclick="apagarItemHistorico(${a.id})">🗑️</button></td></tr>`);
    d.innerHTML = h+"</tbody></table>";
}

function exportarExcel() {
    const filtrados = historicoAlunos.filter(a => a.turma === configAtual.nome);
    if(filtrados.length===0) return alert(`A turma está vazia.`);
    let csv = "DATA;NOME;TURMA;NOTA REDAÇÃO;LINGUAGENS;HUMANAS;MATEMÁTICA;NATUREZA;ACERTOS GERAIS\n";
    filtrados.forEach(a => {
        let nB1 = a.b1 || "0.0"; let nB2 = a.b2 || "0.0"; let nB3 = a.b3 || "0.0"; let nB4 = a.b4 || "0.0";
        csv += `${a.data};${a.nome};${a.turma};${a.redacao};${nB1};${nB2};${nB3};${nB4};${a.total}\n`;
    });
    const blob = new Blob(["\uFEFF" + csv], {type:'text/csv;charset=utf-8;'});
    const link = document.createElement("a"); link.href = URL.createObjectURL(blob); link.download = `relatorio_${configAtual.nome.replace(/\s/g, '_')}.csv`; link.click();
}

// ==========================================
// MÓDULO DE ESTATÍSTICAS (RANKING E ERROS)
// ==========================================
function renderizarEstatisticas() {
    const divRanking = document.getElementById('rankingTurma');
    const divErros = document.getElementById('estatisticasErros');
    if(!divRanking || !divErros) return;

    let filtrados = historicoAlunos.filter(a => a.turma === configAtual.nome);

    if(filtrados.length === 0) {
        divRanking.innerHTML = `<p style="padding: 10px; color: #999;">Sem dados para gerar ranking.</p>`;
        divErros.innerHTML = `<p style="padding: 10px; color: #999;">Sem dados de correção.</p>`;
        return;
    }

    // RANKING
    filtrados.sort((a, b) => b.total - a.total);
    let htmlRanking = `<table class="historico-table" style="background: transparent;"><tbody>`;
    let qtdRanking = filtrados.length > 10 ? 10 : filtrados.length;
    for(let i=0; i < qtdRanking; i++) {
        let medalha = "🏅";
        if(i === 0) medalha = "🥇"; else if(i === 1) medalha = "🥈"; else if(i === 2) medalha = "🥉";
        htmlRanking += `<tr><td style="width:30px; text-align:center; font-size: 1.2rem;">${medalha}</td><td><strong>${filtrados[i].nome}</strong></td><td style="text-align:right;"><b>${filtrados[i].total} pts</b></td></tr>`;
    }
    htmlRanking += `</tbody></table>`;
    divRanking.innerHTML = htmlRanking;

    // RAIO-X DE ERROS
    let contagemErros = {}; 
    filtrados.forEach(aluno => {
        if(aluno.erros && Array.isArray(aluno.erros)) {
            aluno.erros.forEach(q => {
                if(!contagemErros[q]) contagemErros[q] = 0;
                contagemErros[q]++;
            });
        }
    });

    let listaErros = Object.keys(contagemErros).map(q => {
        return { questao: q, quantidade: contagemErros[q] };
    });
    listaErros.sort((a, b) => b.quantidade - a.quantidade);

    if(listaErros.length === 0) {
        divErros.innerHTML = `<p style="padding: 10px; color: #28a745;">Nenhum erro registrado.</p>`;
        return;
    }

    let topErros = listaErros.slice(0, 15);
    let htmlErros = `<table class="historico-table" style="background: transparent;"><tbody>`;
    topErros.forEach((item, index) => {
        let icone = index < 3 ? "🔥" : "⚠️"; 
        
        let nomeMatErro = "Múltiplas";
        configAtual.materias.forEach(m => {
            if(item.questao >= m.inicio && item.questao < (m.inicio + m.qtd)) { nomeMatErro = m.nome; }
        });

        htmlErros += `<tr><td style="width:30px; text-align:center;">${icone}</td><td>Questão <b>${item.questao}</b><br><small style="color:#666;">${nomeMatErro}</small></td><td style="text-align:right; color:#dc3545;"><b>${item.quantidade} erros</b></td></tr>`;
    });
    htmlErros += `</tbody></table>`;
    divErros.innerHTML = htmlErros;
}

// ==========================================
// MÓDULO TABELA GERAL POR ÁREA (MODELO PAC)
// ==========================================

// Agrupa todas as correções salvas por aluno e calcula a média de cada
// área de conhecimento (Linguagem, Ciências Humanas, Matemática, Ciências da Natureza).
// Cuidado: nos blocos do Ensino Médio a ordem é B1=Linguagens, B2=Humanas,
// B3=Natureza, B4=Matemática; no Fundamental é B1=Linguagens, B2=Humanas,
// B3=Matemática, B4=Natureza. Por isso o mapeamento abaixo depende da turma.
function calcularMediasPorAreaConhecimento() {
    const filtrados = historicoAlunos.filter(a => a.turma === configAtual.nome);
    const isEnsinoMedio = configAtual.nome.includes("Médio");

    const porAluno = {};
    filtrados.forEach(a => {
        if(!porAluno[a.nome]) porAluno[a.nome] = { nome: a.nome, linguagem:[], humanas:[], matematica:[], natureza:[] };

        const b1 = parseFloat(a.b1) || 0;
        const b2 = parseFloat(a.b2) || 0;
        const b3 = parseFloat(a.b3) || 0;
        const b4 = parseFloat(a.b4) || 0;

        porAluno[a.nome].linguagem.push(b1);
        porAluno[a.nome].humanas.push(b2);
        if(isEnsinoMedio) {
            porAluno[a.nome].natureza.push(b3);
            porAluno[a.nome].matematica.push(b4);
        } else {
            porAluno[a.nome].matematica.push(b3);
            porAluno[a.nome].natureza.push(b4);
        }
    });

    const media = arr => arr.length ? (arr.reduce((s,v) => s+v, 0) / arr.length) : 0;

    return Object.values(porAluno).map(al => ({
        nome: al.nome,
        linguagem: media(al.linguagem),
        humanas: media(al.humanas),
        matematica: media(al.matematica),
        natureza: media(al.natureza)
    })).sort((a, b) => a.nome.localeCompare(b.nome));
}

function renderizarTabelaPAC() {
    const div = document.getElementById('tabelaPAC');
    if(!div) return;

    const dados = calcularMediasPorAreaConhecimento();
    if(dados.length === 0) {
        div.innerHTML = `<p style="padding:10px; color:#999;">Sem dados suficientes para gerar a tabela desta turma.</p>`;
        return;
    }

    let h = `<table class="historico-table">
                <thead>
                    <tr>
                        <th>Nome</th>
                        <th style="text-align:center;">Linguagem</th>
                        <th style="text-align:center;">Ciências Humanas</th>
                        <th style="text-align:center;">Matemática</th>
                        <th style="text-align:center;">Ciências da Natureza</th>
                    </tr>
                </thead>
                <tbody>`;
    dados.forEach(a => {
        h += `<tr>
                <td><strong>${a.nome}</strong></td>
                <td style="text-align:center;">${a.linguagem.toFixed(1)}</td>
                <td style="text-align:center;">${a.humanas.toFixed(1)}</td>
                <td style="text-align:center;">${a.matematica.toFixed(1)}</td>
                <td style="text-align:center;">${a.natureza.toFixed(1)}</td>
              </tr>`;
    });
    h += `</tbody></table>`;
    div.innerHTML = h;
}

function exportarTabelaPAC() {
    const dados = calcularMediasPorAreaConhecimento();
    if(dados.length === 0) return alert("Não há dados suficientes para gerar a tabela desta turma.");

    if(typeof XLSX === 'undefined') {
        alert("Biblioteca de exportação Excel não carregou. Verifique sua conexão com a internet e tente novamente.");
        return;
    }

    // Segue o mesmo modelo do arquivo de tabelas do PAC:
    // linha 1 = nome da turma, linha 2 = cabeçalho, linhas seguintes = alunos.
    const linhas =[
        [configAtual.nome, "", "", "", ""],
        ["Nome", "Linguagem", "Ciencias Humanas", "Matemática e suas tecnologias", "Ciencias da Natureza"]
    ];

    dados.forEach(a => {
        linhas.push([
            a.nome,
            Number(a.linguagem.toFixed(1)),
            Number(a.humanas.toFixed(1)),
            Number(a.matematica.toFixed(1)),
            Number(a.natureza.toFixed(1))
        ]);
    });

    const ws = XLSX.utils.aoa_to_sheet(linhas);
    ws['!cols'] =[{wch:35}, {wch:15}, {wch:18}, {wch:28}, {wch:18}];
    ws['!merges'] =[{ s: {r:0, c:0}, e: {r:0, c:4} }];

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Notas");

    XLSX.writeFile(wb, `tabela_PAC_${configAtual.nome.replace(/\s/g, '_')}.xlsx`);
}

// ==========================================
// MÓDULO DE GESTÃO DE ALUNOS (FIREBASE)
// ==========================================

async function carregarAlunosDoFirebase() {
    if(!db) return;
    try {
        const snapshot = await db.collection("alunos").get();
        alunosDB =[];
        snapshot.forEach(doc => { 
            let aluno = doc.data();
            aluno.id = doc.id; 
            alunosDB.push(aluno); 
        });
        
        const optGroupsAdmin = document.getElementById('selTurmaAdmin').innerHTML;
        document.getElementById('novoTurmaAluno').innerHTML = optGroupsAdmin;
        document.getElementById('turmaDestinoTransferencia').innerHTML = optGroupsAdmin;
        
        atualizarListasDeAlunosUI();
    } catch(e) { console.error("Erro ao carregar alunos", e); }
}

function atualizarListasDeAlunosUI() {
    const turmaSelecionada = configAtual.nome; 
    let alunosDaTurma = alunosDB.filter(a => a.turma === turmaSelecionada);
    
    // Organiza em ordem alfabética
    alunosDaTurma.sort((a, b) => a.nome.localeCompare(b.nome));

    const selectCorrecao = document.getElementById('nomeAluno');
    if(selectCorrecao) {
        selectCorrecao.innerHTML = "";
        if(alunosDaTurma.length === 0) {
            selectCorrecao.innerHTML = `<option value="">-- Nenhum aluno cadastrado nesta turma --</option>`;
        } else {
            alunosDaTurma.forEach(a => { selectCorrecao.innerHTML += `<option value="${a.nome}">${a.nome}</option>`; });
        }
    }

    const divTabela = document.getElementById('tabelaAlunos');
    const spanTotal = document.getElementById('totalAlunosTurma');
    if(!divTabela) return;

    if(spanTotal) {
        spanTotal.innerHTML = `<span style="background: var(--primary); color: white; padding: 4px 10px; border-radius: 12px; font-weight: bold;">Total: ${alunosDaTurma.length}</span>`;
    }

    if(alunosDaTurma.length === 0) {
        divTabela.innerHTML = `<p style='text-align:center;color:#999; padding: 20px;'>Sem alunos. Adicione acima.</p>`;
        return;
    }

    // NOVA TABELA COM CHECKBOX PARA SELEÇÃO
    let h = `<table class="historico-table">
                <thead>
                    <tr>
                        <th style="width: 30px; text-align: center;"><input type="checkbox" onchange="document.querySelectorAll('.chk-aluno').forEach(c => c.checked = this.checked)" title="Selecionar Todos"></th>
                        <th style="width: 40px; text-align: center;">Nº</th>
                        <th>Nome do Aluno</th>
                        <th style="text-align:center; width: 100px;">Ações</th>
                    </tr>
                </thead>
                <tbody>`;
    
    alunosDaTurma.forEach((a, index) => {
        h += `<tr>
            <td style="text-align: center;"><input type="checkbox" class="chk-aluno" value="${a.id}"></td>
            <td style="text-align: center; color: #666; font-weight: bold;">${index + 1}</td>
            <td><strong>${a.nome}</strong></td>
            <td style="text-align:center;">
                <button class="btn-apagar" style="color:#0056b3;" onclick="editarAluno('${a.id}', '${a.nome}')" title="Editar">✏️</button>
                <button class="btn-apagar" onclick="excluirAluno('${a.id}', '${a.nome}')" title="Excluir">🗑️</button>
            </td>
        </tr>`;
    });
    
    h += `</tbody></table>`;
    divTabela.innerHTML = h;
}

async function cadastrarAluno() {
    const nomeInput = document.getElementById('novoNomeAluno');
    const turmaInput = document.getElementById('novoTurmaAluno');
    const nome = nomeInput.value.trim().toUpperCase(); 
    const codigoTurma = turmaInput.value;
    const nomeTurma = BANCO_DE_PROVAS[codigoTurma].nome; 

    if(!nome) return alert("Digite o nome do aluno!");

    const novoAluno = { nome: nome, turma: nomeTurma, dataCadastro: new Date().toISOString() };
    
    try {
        const docRef = await db.collection("alunos").add(novoAluno);
        novoAluno.id = docRef.id;
        alunosDB.push(novoAluno);
        
        nomeInput.value = ""; 
        atualizarListasDeAlunosUI();
    } catch(e) { alert("Erro ao salvar no banco de dados."); }
}

async function excluirAluno(id, nome) {
    if(confirm(`Tem certeza que deseja EXCLUIR o aluno ${nome}?`)) {
        try {
            await db.collection("alunos").doc(id).delete();
            alunosDB = alunosDB.filter(a => a.id !== id);
            atualizarListasDeAlunosUI();
        } catch(e) { alert("Erro ao excluir."); }
    }
}

async function editarAluno(id, nomeAtual) {
    let novoNome = prompt("Editar nome do aluno:", nomeAtual);
    if(novoNome && novoNome.trim() !== "" && novoNome !== nomeAtual) {
        novoNome = novoNome.trim().toUpperCase();
        try {
            await db.collection("alunos").doc(id).update({ nome: novoNome });
            let index = alunosDB.findIndex(a => a.id === id);
            if(index > -1) alunosDB[index].nome = novoNome;
            atualizarListasDeAlunosUI();
        } catch(e) { alert("Erro ao editar."); }
    }
}

// NOVA FUNÇÃO: MOVE APENAS OS ALUNOS SELECIONADOS
async function transferirTurmaSelecionados() {
    const checkboxes = document.querySelectorAll('.chk-aluno:checked');
    if(checkboxes.length === 0) return alert("Selecione pelo menos um aluno marcando a caixinha ao lado do nome!");

    const turmaAtual = configAtual.nome;
    const codigoDestino = document.getElementById('turmaDestinoTransferencia').value;
    const turmaDestino = BANCO_DE_PROVAS[codigoDestino].nome;

    if(turmaAtual === turmaDestino) return alert("A turma de destino não pode ser igual à atual!");

    if(confirm(`Você vai mover ${checkboxes.length} aluno(s) do ${turmaAtual} para o ${turmaDestino}. Confirma?`)) {
        const btn = document.querySelector("button[onclick='transferirTurmaSelecionados()']");
        if(btn) btn.innerText = "Movendo...";
        
        try {
            const batch = db.batch();
            
            checkboxes.forEach(chk => {
                const idAluno = chk.value;
                const ref = db.collection("alunos").doc(idAluno);
                batch.update(ref, { turma: turmaDestino });
                
                // Atualiza na memória para refletir na tela
                let alunoIndex = alunosDB.findIndex(a => a.id === idAluno);
                if(alunoIndex > -1) alunosDB[alunoIndex].turma = turmaDestino; 
            });
            
            await batch.commit();
            alert("Sucesso! Alunos transferidos.");
            atualizarListasDeAlunosUI();
            if(btn) btn.innerText = "Mover Selecionados 🚀";
        } catch(e) { 
            alert("Erro ao transferir alunos em massa."); 
            console.error(e); 
            if(btn) btn.innerText = "Mover Selecionados 🚀";
        }
    }
}

// ==========================================
// MAPEAMENTO 
// ==========================================
function iniciarMapeamento() { if(!imgAtual.src) return alert("Carregue uma imagem!"); resetMapeamento(); }
function resetMapeamento() { estadoMap=1; indiceDisc=0; mapaTemp=[]; atualizarTextoMap(); }
function copiarCodigo() { document.getElementById('outputCodigo').select(); document.execCommand('copy'); const btn = document.getElementById('btnCopiar'); btn.innerText = "✅ Copiado!"; setTimeout(() => btn.innerText = "📋 Copiar Código", 2000); }

function atualizarTextoMap() {
    const txt = document.getElementById('instrucaoTexto'); const qtdPrimeira = configAtual.materias[0].qtd; const nomePrimeira = configAtual.materias[0].nome;
    if(estadoMap===1) txt.innerHTML = `<b>PASSO 1:</b> Clique <b>01-A</b> (${nomePrimeira})`; else if(estadoMap===2) txt.innerHTML = `<b>PASSO 2:</b> Clique <b>01-E</b> (Largura)`; else if(estadoMap===3) txt.innerHTML = `<b>PASSO 3:</b> Clique <b>${qtdPrimeira}-A</b> (Altura)`; else if(estadoMap===4 && indiceDisc < configAtual.materias.length) { txt.innerHTML = `<b>PASSO 4:</b> Clique Letra A de <b>${configAtual.materias[indiceDisc].nome}</b>`; } else if(indiceDisc >= configAtual.materias.length) txt.innerHTML = "<b>FIM! Copie o código gerado.</b>";
}

if(canvasEl) {
    canvasEl.addEventListener('mousedown', e => {
        if(!document.getElementById('tab-mapear').classList.contains('active') || !imgAtual.src) return;
        const rect = canvasEl.getBoundingClientRect(); const scaleX = canvasEl.width / rect.width; const scaleY = canvasEl.height / rect.height; const x = (e.clientX - rect.left) * scaleX; const y = (e.clientY - rect.top) * scaleY;
        ctx.strokeStyle = "blue"; ctx.lineWidth = 4; ctx.beginPath(); ctx.moveTo(x-10,y-10); ctx.lineTo(x+10,y+10); ctx.moveTo(x+10,y-10); ctx.lineTo(x-10,y+10); ctx.stroke();
        if(estadoMap === 1) { calib.xA=x; calib.yA=y; estadoMap=2; } else if(estadoMap === 2) { calib.distX = (x-calib.xA)/4; estadoMap=3; } else if(estadoMap === 3) { const qtdPrimeira = configAtual.materias[0].qtd; calib.distY = (y-calib.yA)/(qtdPrimeira - 1); estadoMap=4; } else if(estadoMap === 4) { if(indiceDisc < configAtual.materias.length) { gerarBlocoDisciplina(x, y, configAtual.materias[indiceDisc]); indiceDisc++; if(indiceDisc >= configAtual.materias.length) finalizarMapeamento(); } }
        atualizarTextoMap();
    });
}

function gerarBlocoDisciplina(xBase, yBase, config) {
    for(let i=0; i<config.qtd; i++) {
        let qNum = config.inicio + i; let y = yBase + (i * calib.distY);["A","B","C","D","E"].forEach((letra, idx) => {
            let x = xBase + (idx * calib.distX); mapaTemp.push({ id:`Q${qNum}-${letra}`, questao:qNum, alt:letra, x:Math.round(x), y:Math.round(y), w:Math.round(calib.distX*0.7), h:Math.round(calib.distY*0.7) });
            ctx.strokeStyle = "lime"; ctx.lineWidth = 2; ctx.strokeRect(x-(calib.distX*0.35), y-(calib.distY*0.35), calib.distX*0.7, calib.distY*0.7);
        });
    }
}

function finalizarMapeamento() { document.getElementById('areaCodigo').style.display='block'; document.getElementById('outputCodigo').value = JSON.stringify(mapaTemp); }
